","keccak256":"0x69f54c02b7d81d505910ec198c11ed4c6a728418a868b906b4a0cf29946fda84","license":"MIT"},"contracts/Pump.sol":{"content":"// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.26;

import "@openzeppelin/contracts/proxy/Clones.sol";
import "@openzeppelin/contracts/access/Ownable2Step.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "./interface/IPump.sol";
import "./Token.sol";
import "./interface/IIPShare.sol";
import "./interface/IBondingCurve.sol";

import "./solady/src/utils/FixedPointMathLib.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";

contract Pump is Ownable2Step, IPump, ReentrancyGuard, IBondingCurve {
    address private ipshare;
    address public tokenImplementation;
    uint256 public createFee = 0.01 ether;
    uint256 private claimFee = 0.0005 ether;
    uint256 private divisor = 10000;
    uint256 private secondPerDay = 86400;
    address private feeReceiver = 0x06Deb72b2e156Ddd383651aC3d2dAb5892d9c048;
    address private claimSigner = 0x78C2aF38330C5b41Ae7946A313e43cDCEEaf8611;
    uint256[2] private feeRatio = [100, 100]; // 0: to tiptag; 1: to salesman

    // PancakeSwap V4 (Infinity)
    address private poolManager = 0xa0FfB9c1CE1Fe56963B0321B32E7A0302114058b; // BSC CLPoolManager
    address private vault = 0x238a358808379702088667322f80aC48bAd5e6c4; // BSC Vault
    address private hookAddress; // TipTagSwapHook address

    mapping(address => bool) public createdTokens;
    mapping(string => bool) public createdTicks;
    mapping(address => uint256) private createdSaltsIndex;

    // social distribution
    uint256 private constant claimAmountPerSecond = 12.87 ether;
    mapping(address => uint256) private lastClaimTime;
    mapping(address => mapping(uint256 => bool)) public claimedOrder;
    mapping(address => uint256) public pendingClaimSocialRewards;
    mapping(address => uint256) public totalClaimedSocialRewards;
    uint256 public totalTokens;

    /**
     * @param _ipshare IPShare contract address
     * @param _tokenImplementation Token implementation address (used for clone)
     * @param _feeReceiver Fee receiver address, pass address(0) to use default
     */
    constructor(address _ipshare, address _tokenImplementation, address _feeReceiver) Ownable(msg.sender) {
        ipshare = _ipshare;
        tokenImplementation = _tokenImplementation;
        if (_feeReceiver != address(0)) feeReceiver = _feeReceiver;
    }

    function adminSetPoolManager(address _poolManager) public onlyOwner {
        poolManager = _poolManager;
    }

    function adminSetVault(address _vault) public onlyOwner {
        vault = _vault;
    }

    function adminSetHookAddress(address _hookAddress) public onlyOwner {
        hookAddress = _hookAddress;
    }

    receive() external payable {}

    // admin function
    function adminChangeIPShare(address _ipshare) public onlyOwner {
        emit IPShareChanged(ipshare, _ipshare);
        ipshare = _ipshare;
    }

    function adminChangeCreateFee(uint256 _createFee) public onlyOwner {
        if (_createFee > 1 ether) {
            revert TooMuchFee();
        }
        emit CreateFeeChanged(createFee, _createFee);
        createFee = _createFee;
    }

    function adminChangeFeeRatio(uint256[2] calldata ratios) public onlyOwner {
        if (ratios[0] > 1000 || ratios[1] > 1000) {
            revert TooMuchFee();
        }
        feeRatio = ratios;
        emit FeeRatiosChanged(ratios[0], ratios[1]);
    }

    function adminChangeClaimSigner(address signer) public onlyOwner {
        emit ClaimSignerChanged(claimSigner, signer);
        claimSigner = signer;
    }

    function adminSetClaimFee(uint256 _claimFee) public onlyOwner {
        if (_claimFee > 0.02 ether) {
            revert TooMuchFee();
        }
        emit ClaimFeeChanged(claimFee, _claimFee);
        claimFee = _claimFee;
    }

    function adminChangeTokenImplementation(address _tokenImplementation) public onlyOwner {
        emit TokenImplementationChanged(tokenImplementation, _tokenImplementation);
        tokenImplementation = _tokenImplementation;
    }

    function adminChangeFeeAddress(address _feeReceiver) public onlyOwner {
        emit FeeAddressChanged(feeReceiver, _feeReceiver);
        feeReceiver = _feeReceiver;
    }

    function getIPShare() public view override returns (address) {
        return ipshare;
    }

    function getFeeReceiver() public view override returns (address) {
        return feeReceiver;
    }

    function getFeeRatio() public view override returns (uint256[2] memory) {
        return feeRatio;
    }
    function getClaimFee() public view override returns (uint256) {
        return claimFee;
    }

    function getClaimSigner() public view override returns (address) {
        return claimSigner;
    }

    function getPoolManager() public view override returns (address) {
        return poolManager;
    }

    function getVault() public view override returns (address) {
        return vault;
    }

    function getHookAddress() public view override returns (address) {
        return hookAddress;
    }

    function getLastSaltIndex(address user) public view returns (uint256) {
        return createdSaltsIndex[user];
    }

    function createToken(string calldata tick, bytes32 salt) public payable override nonReentrant returns (address) {
        // Only EOA can create token (prevent phishing via tx.origin)
        require(msg.sender == tx.origin, "Only EOA");

        if (createdTicks[tick]) {
            revert TickHasBeenCreated();
        }
        if (uint256(salt) <= createdSaltsIndex[msg.sender]) {
            revert SaltNotAvailable();
        }
        createdTicks[tick] = true;

        // check user created ipshare
        address creator = msg.sender;
        bool needCreateIPShare = !IIPShare(ipshare).ipshareCreated(creator);
        uint256 ipshareCreateFee = 0;
        if (needCreateIPShare) {
            ipshareCreateFee = IIPShare(ipshare).createFee();
        }

        uint256 totalFixedFee = createFee + ipshareCreateFee;

        // cost fee
        if (msg.value < totalFixedFee) {
            revert InsufficientCreateFee();
        }

        // auto create IPShare for creator and pass-through create fee if needed
        if (needCreateIPShare) {
            IIPShare(ipshare).createShare{value: ipshareCreateFee}(creator);
        }

        if (createFee > 0) {
            (bool success, ) = feeReceiver.call{value: createFee}("");
            if (!success) {
                revert InsufficientCreateFee();
            }
        }

        // Deploy token via clone + CREATE2 (lower gas, deterministic address)
        bytes32 cloneSalt = keccak256(abi.encode(msg.sender, salt));
        address instance = Clones.cloneDeterministic(tokenImplementation, cloneSalt);
        createdSaltsIndex[msg.sender] = uint256(salt);

        emit NewToken(tick, instance, creator);

        Token(payable(instance)).initialize(address(this), creator, tick);

        // before dawn of today
        lastClaimTime[instance] = block.timestamp - (block.timestamp % secondPerDay) - 1;

        if (msg.value > totalFixedFee) {
            (bool success1, bytes memory receiveAmount) = instance.call{value: msg.value - totalFixedFee}(
                abi.encodeWithSignature("buyToken(uint256,address,uint16)", 0, creator, 0)
            );
            if (!success1) {
                revert PreMineTokenFail();
            }
            uint256 receiveAmountUint = abi.decode(receiveAmount, (uint256));

            IERC20(instance).transfer(msg.sender, receiveAmountUint);
            uint256 leftValue = address(this).balance;
            if (leftValue > 0) {
                (bool success2, ) = msg.sender.call{value: leftValue}("");
                if (!success2) {
                    revert RefundFail();
                }
            }
        }
        createdTokens[instance] = true;
        totalTokens += 1;
        return instance;
    }

    /**
     * Predict the cloned token address from deployer and salt.
     */
    function predictTokenAddress(address deployer, bytes32 salt) public view returns (address) {
        bytes32 cloneSalt = keccak256(abi.encode(deployer, salt));
        return Clones.predictDeterministicAddress(tokenImplementation, cloneSalt, address(this));
    }

    /********************************** social distribution ********************************/
    function calculateReward(uint256 from, uint256 to) public pure returns (uint256 rewards) {
        if (from >= to) return 0;
        return (to - from) * claimAmountPerSecond;
    }

    // set distributed rewards can be claimed by user
    function claimPendingSocialRewards(address token) public {
        // calculate rewards
        uint256 rewards = calculateReward(lastClaimTime[token], block.timestamp);
        if (rewards > 0) {
            pendingClaimSocialRewards[token] += rewards;
            lastClaimTime[token] = block.timestamp;
            emit ClaimDistributedReward(token, block.timestamp, rewards);
        }
    }

    function userClaim(address token, uint256 orderId, uint256 amount, bytes calldata signature) public payable {
        if (!IToken(token).listed()) {
            revert TokenNotListed();
        }
        if (claimedOrder[token][orderId]) {
            revert ClaimOrderExist();
        }
        if (signature.length != 65) {
            revert InvalidSignature();
        }
        if (!createdTokens[token]) {
            revert TokenNotCreated();
        }

        if (msg.value < claimFee) {
            revert CostFeeFail();
        } else {
            (bool success, ) = feeReceiver.call{value: claimFee}("");
            if (!success) {
                revert CostFeeFail();
            }
        }

        bytes32 data = keccak256(abi.encodePacked(block.chainid, token, orderId, msg.sender, amount));

        if (!_check(data, signature)) {
            revert InvalidSignature();
        }

        if (pendingClaimSocialRewards[token] < amount) {
            claimPendingSocialRewards(token);
        }

        if (pendingClaimSocialRewards[token] < amount) {
            revert InvalidClaimAmount();
        }

        pendingClaimSocialRewards[token] -= amount;
        totalClaimedSocialRewards[token] += amount;

        claimedOrder[token][orderId] = true;

        IERC20(token).transfer(msg.sender, amount);

        emit UserClaimReward(token, orderId, msg.sender, amount);
    }

    function _check(bytes32 data, bytes calldata sign) internal view returns (bool) {
        // Use OZ ECDSA to handle v/r/s parsing and malleability checks internally.
        bytes32 ethSignedHash = keccak256(abi.encodePacked("\x19Ethereum Signed Message:\n32", data));
        address addr = ECDSA.recover(ethSignedHash, sign);
        return addr == claimSigner;
    }

    /********************************** bonding curve ********************************/

    /**
     * calculate the eth price when user buy amount tokens
     */
    function getPrice(uint256 supply, uint256 amount) public pure override returns (uint256) {
        require(supply <= 1000000000 ether && amount <= 1000000000 ether, "supply or amount too large");
        uint256 a = 6_500_000_000;
        uint256 b = 2.5175516438e26;
        uint256 x = FixedPointMathLib.mulWad(a, b);
        uint256 e1 = uint256(FixedPointMathLib.expWad(int256(((supply + amount) * 1e18) / b)));
        uint256 e2 = uint256(FixedPointMathLib.expWad(int256(((supply) * 1e18) / b)));
        return FixedPointMathLib.mulWad(e1 - e2, x);
    }

    function getSellPrice(uint256 supply, uint256 amount) public pure override returns (uint256) {
        return getPrice(supply - amount, amount);
    }

    function getBuyPriceAfterFee(uint256 supply, uint256 amount) public view override returns (uint256) {
        uint256 price = getPrice(supply, amount);
        return ((price * divisor) / (divisor - feeRatio[0] - feeRatio[1]));
    }

    function getSellPriceAfterFee(uint256 supply, uint256 amount) public view override returns (uint256) {
        uint256 price = getSellPrice(supply, amount);
        return (price * (divisor - feeRatio[0] - feeRatio[1])) / divisor;
    }

    function getBuyAmountByValue(uint256 bondingCurveSupply, uint256 ethAmount) public pure override returns (uint256) {
        require(bondingCurveSupply <= 1000000000 ether && ethAmount <= 1000000000 ether, "supply or amount too large");
        uint256 a = 6_500_000_000;
        uint256 b = 2.5175516438e26;
        // b * ln(ethAmount / (a*b) + exp(bondingCurveSupply/b)) - bondingCurveSupply;
        uint256 ab = FixedPointMathLib.mulWad(a, b);
        uint256 sab = FixedPointMathLib.divWad(ethAmount, ab);
        uint256 e = uint256(FixedPointMathLib.expWad(int256((bondingCurveSupply * 1e18) / b)));
        uint256 ln = uint256(FixedPointMathLib.lnWad(int256(sab + e)));
        return FixedPointMathLib.mulWad(b, ln) - bondingCurveSupply;
    }
}
","keccak256":"0x4bfcb351b84c9e1cbe890932f694bf10309df67867b8b0385e156aa2cc53defb","license":"UNLICENSED"},"contracts/Token.sol":{"content":"// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.26;

import {ERC20} from "./solady/src/tokens/ERC20.sol";

import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "./interface/IToken.sol";
import "./interface/IIPShare.sol";
import "./interface/IPump.sol";
import "./interface/IBondingCurve.sol";

// PancakeSwap V4 (Infinity)
import {ICLPoolManager} from "infinity-core/src/pool-cl/interfaces/ICLPoolManager.sol";
import {IHooks} from "infinity-core/src/interfaces/IHooks.sol";
import {ILockCallback} from "infinity-core/src/interfaces/ILockCallback.sol";
import {IVault} from "infinity-core/src/interfaces/IVault.sol";
import {PoolKey} from "infinity-core/src/types/PoolKey.sol";
import {PoolId, PoolIdLibrary} from "infinity-core/src/types/PoolId.sol";
import {Currency, CurrencyLibrary} from "infinity-core/src/types/Currency.sol";
import {BalanceDelta} from "infinity-core/src/types/BalanceDelta.sol";
import {CLPoolParametersHelper} from "infinity-core/src/pool-cl/libraries/CLPoolParametersHelper.sol";
import {IPoolManager} from "infinity-core/src/interfaces/IPoolManager.sol";

interface ITipTagSwapHook {
    function registerPool(PoolId poolId, address token) external;
}

contract Token is IToken, ERC20, ReentrancyGuard, ILockCallback {
    using PoolIdLibrary for PoolKey;
    using CurrencyLibrary for Currency;

    string private _name;
    string private _symbol;
    uint256 private constant divisor = 10000;
    address private constant BlackHole = 0x000000000000000000000000000000000000dEaD;

    // distribute token total amount
    uint256 private constant socialDistributionAmount = 150000000 ether;
    uint256 private constant bondingCurveTotalAmount = 650000000 ether;
    uint256 private constant liquidityAmount = 200000000 ether;

    uint256 public bondingCurveSupply = 0;

    // Anti-snipe: within 15s after creation, sellsmanFee decays quadratically from 80% to Pump's feeRatio[1]
    uint256 public createdAt;
    uint256 private constant ANTI_SNIPE_WINDOW = 15;
    uint256 private constant ANTI_SNIPE_SELLSMAN_FEE_MAX = 8000; // 80%
    uint256 private constant ANTI_SNIPE_DENOM = 225; // 15^2, used for quadratic decay

    // state
    address private manager; // pump contract address
    address public ipshareSubject;
    IBondingCurve public bondingCurve;
    bool public listed = false;
    bool initialized = false;

    // PCS V4 pool info
    ICLPoolManager public clPoolManager;
    IVault public vault;
    PoolId public v4PoolId;
    // In V4, tickSpacing and fee are fully decoupled.
    // fee=0 means zero native pool fee; all fees are collected by TipTagSwapHook.
    // tickSpacing=60 controls price-tick granularity only (no 0.3% DEX fee implied).
    int24 public constant TICK_SPACING = 60;
    // Calibrated initial price for bounded-range listing so 19 ETH + 200M TOKEN are both used as much as possible.
    uint160 private constant INITIAL_SQRT_PRICE_X96 = 27302121365878665742458286;
    uint256 private constant LISTING_ETH_AMOUNT = 19 ether;
    uint256 private constant LISTING_TOKEN_AMOUNT = 200000000 ether;
    // Precomputed listing constants for fixed strategy.
    int24 private constant LISTING_TICK_LOWER = -191700;
    int24 private constant LISTING_TICK_UPPER = 887220;
    uint128 private constant LISTING_LIQUIDITY_DELTA = 6547423157242855;

    receive() external payable {
        if (!listed) {
            buyToken(0, address(0), 0);
        }
    }

    function getIPShare() external view returns (address) {
        return ipshareSubject;
    }

    function initialize(address manager_, address ipshareSubject_, string memory tick) public {
        if (initialized) {
            revert TokenInitialized();
        }
        initialized = true;
        createdAt = block.timestamp;
        manager = manager_;
        ipshareSubject = ipshareSubject_;
        bondingCurve = IBondingCurve(manager_);
        _name = tick;
        _symbol = tick;
        _mint(address(this), bondingCurveTotalAmount + liquidityAmount);
        _mint(address(manager), socialDistributionAmount);

        // Set PCS V4 references
        clPoolManager = ICLPoolManager(IPump(manager).getPoolManager());
        vault = IVault(IPump(manager).getVault());
    }

    /********************************** bonding curve ********************************/
    function buyToken(
        uint256 expectAmount,
        address sellsman,
        uint16 slippage
    ) public payable nonReentrant returns (uint256) {
        require(msg.sender != address(clPoolManager), "can't buy token from pool");
        sellsman = _checkBondingCurveState(sellsman);
        (uint256 tiptagFeePercent, uint256 sellsmanFeePercent) = _getBuyFeeRatiosView();
        uint256 buyFunds = msg.value;
        uint256 tiptagFee = (msg.value * tiptagFeePercent) / divisor;
        uint256 sellsmanFee = (msg.value * sellsmanFeePercent) / divisor;

        if (sellsmanFee < 100000000) {
            revert DustIssue();
        }

        uint256 tokenReceived = bondingCurve.getBuyAmountByValue(
            bondingCurveSupply,
            buyFunds - tiptagFee - sellsmanFee
        );

        address tiptapFeeAddress = IPump(manager).getFeeReceiver();

        if (tokenReceived + bondingCurveSupply >= bondingCurveTotalAmount) {
            uint256 actualAmount = bondingCurveTotalAmount - bondingCurveSupply;
            if (slippage > 0 && (actualAmount < (expectAmount * (divisor - slippage)) / divisor)) {
                revert OutOfSlippage();
            }
            return _buyTokenFillToCap(actualAmount, tiptagFeePercent, sellsmanFeePercent, sellsman);
        } else {
            // Normal buy: fees already computed at entry using dynamic ratios from _getBuyFeeRatiosView()
            if (slippage > 0 && (tokenReceived < (expectAmount * (divisor - slippage)) / divisor)) {
                revert OutOfSlippage();
            }

            // CEI: update state before external calls
            bondingCurveSupply += tokenReceived;
            this.transfer(msg.sender, tokenReceived);

            (bool success, ) = tiptapFeeAddress.call{value: tiptagFee}("");
            if (!success) {
                revert CostFeeFail();
            }

            address feeRecipient = _getFeeRecipient(sellsman);
            IIPShare(IPump(manager).getIPShare()).valueCapture{value: sellsmanFee}(feeRecipient);
            emit Trade(msg.sender, feeRecipient, true, tokenReceived, msg.value, tiptagFee, sellsmanFee);
            return tokenReceived;
        }
    }

    function sellToken(uint256 amount, uint256 expectReceive, address sellsman, uint16 slippage) public nonReentrant {
        sellsman = _checkBondingCurveState(sellsman);

        uint256 sellAmount = amount;
        if (balanceOf(msg.sender) < sellAmount) {
            sellAmount = balanceOf(msg.sender);
        }

        if (sellAmount < 100000000) {
            revert DustIssue();
        }

        uint256 afterSupply = 0;
        afterSupply = bondingCurveSupply - sellAmount;

        uint256 price = bondingCurve.getPrice(afterSupply, sellAmount);

        uint256[2] memory feeRatio = IPump(manager).getFeeRatio();
        address tiptagFeeAddress = IPump(manager).getFeeReceiver();

        uint256 tiptagFee = (price * feeRatio[0]) / divisor;
        uint256 sellsmanFee = (price * feeRatio[1]) / divisor;
        uint256 receivedEth = price - tiptagFee - sellsmanFee;

        if (expectReceive > 0 && slippage > 0 && (receivedEth < ((divisor - slippage) * expectReceive) / divisor)) {
            revert OutOfSlippage();
        }

        // CEI: update state before external calls
        transfer(address(this), sellAmount);
        bondingCurveSupply -= sellAmount;

        {
            (bool success1, ) = tiptagFeeAddress.call{value: tiptagFee}("");
            (bool success2, ) = msg.sender.call{value: receivedEth}("");
            if (!success1 || !success2) {
                revert RefundFail();
            }
        }

        address feeRecipient = _getFeeRecipient(sellsman);
        IIPShare(IPump(manager).getIPShare()).valueCapture{value: sellsmanFee}(feeRecipient);
        emit Trade(msg.sender, feeRecipient, false, sellAmount, price, tiptagFee, sellsmanFee);
    }

    /**
     * Get current buy fee ratios (basis points, e.g. 100 = 1%).
     * 1. First buy (bondingCurveSupply == 0): uses Pump's feeRatio as-is.
     * 2. Within 15s after creation: tiptag = feeRatio[0]; sellsman decays quadratically from 80% to feeRatio[1].
     * 3. After 15s: uses Pump's configured feeRatio.
     */
    function getBuyFeeRatios() external view returns (uint256 tiptagFeePercent, uint256 sellsmanFeePercent) {
        return _getBuyFeeRatiosView();
    }

    function _getBuyFeeRatiosView() private view returns (uint256 tiptagFeePercent, uint256 sellsmanFeePercent) {
        uint256[2] memory feeRatio = IPump(manager).getFeeRatio();
        if (bondingCurveSupply == 0) {
            return (feeRatio[0], feeRatio[1]);
        }
        uint256 elapsed = block.timestamp - createdAt;
        if (elapsed >= ANTI_SNIPE_WINDOW) {
            return (feeRatio[0], feeRatio[1]);
        }
        uint256 remaining = ANTI_SNIPE_WINDOW - elapsed;
        sellsmanFeePercent =
            feeRatio[1] +
            ((ANTI_SNIPE_SELLSMAN_FEE_MAX - feeRatio[1]) * remaining * remaining) /
            ANTI_SNIPE_DENOM;
        return (feeRatio[0], sellsmanFeePercent);
    }

    function _buyTokenFillToCap(
        uint256 actualAmount,
        uint256 tiptagFeePercent,
        uint256 sellsmanFeePercent,
        address sellsman
    ) private returns (uint256) {
        uint256 priceBeforeFee = bondingCurve.getPrice(bondingCurveSupply, actualAmount);
        uint256 usedEth = (priceBeforeFee * divisor) / (divisor - tiptagFeePercent - sellsmanFeePercent);
        if (usedEth > msg.value) revert InsufficientFund();
        if (usedEth < msg.value) {
            (bool ok, ) = msg.sender.call{value: msg.value - usedEth}("");
            if (!ok) revert RefundFail();
        }
        uint256 tiptagFee = (usedEth * tiptagFeePercent) / divisor;
        uint256 sellsmanFee = (usedEth * sellsmanFeePercent) / divisor;
        address tiptapFeeAddress = IPump(manager).getFeeReceiver();
        // CEI: update state before external calls
        bondingCurveSupply += actualAmount;
        this.transfer(msg.sender, actualAmount);

        (bool success1, ) = tiptapFeeAddress.call{value: tiptagFee}("");
        if (!success1) revert CostFeeFail();
        address feeRecipient = _getFeeRecipient(sellsman);
        IIPShare(IPump(manager).getIPShare()).valueCapture{value: sellsmanFee}(feeRecipient);
        emit Trade(msg.sender, feeRecipient, true, actualAmount, usedEth, tiptagFee, sellsmanFee);
        _makeLiquidityPool();
        return actualAmount;
    }

    function _checkBondingCurveState(address sellsman) private returns (address) {
        if (listed) {
            revert TokenListed();
        }
        if (sellsman == address(0)) {
            sellsman = ipshareSubject;
        } else if (!IIPShare(IPump(manager).getIPShare()).ipshareCreated(sellsman)) {
            revert IPShareNotCreated();
        }
        return sellsman;
    }

    /// @notice 动态交易期（15s 内）费用固定归部署者，防止 MEV 攻击者通过传入自己为 sellsman 回收费用
    function _getFeeRecipient(address sellsman) private view returns (address) {
        if (block.timestamp - createdAt < ANTI_SNIPE_WINDOW) {
            return ipshareSubject;
        }
        return sellsman;
    }

    /********************************** to dex (PancakeSwap V4 Infinity) ********************************/
    function _makeLiquidityPool() private {
        require(address(this).balance >= LISTING_ETH_AMOUNT, "Insufficient ETH for listing");
        require(balanceOf(address(this)) >= LISTING_TOKEN_AMOUNT, "Insufficient token for listing");

        // 1. Build the PoolKey (PCS V4 format)
        //    currency0 = Native ETH (address(0)), currency1 = Token
        //    tickSpacing is encoded in bytes32 parameters (bits [16-39])
        address hookAddr = IPump(manager).getHookAddress();

        uint16 hookBitmap = hookAddr == address(0) ? 0 : IHooks(hookAddr).getHooksRegistrationBitmap();
        bytes32 parameters = CLPoolParametersHelper.setTickSpacing(bytes32(uint256(hookBitmap)), TICK_SPACING);

        PoolKey memory poolKey = PoolKey({
            currency0: CurrencyLibrary.NATIVE, // Native ETH
            currency1: Currency.wrap(address(this)), // Token
            hooks: IHooks(hookAddr),
            poolManager: IPoolManager(address(clPoolManager)),
            fee: 0, // No native LP fee, all fees via Hook
            parameters: parameters
        });

        // 2. Use fixed initial price to avoid runtime price drift and overflow edge-cases.
        uint160 sqrtPriceX96 = INITIAL_SQRT_PRICE_X96;

        // 3. Use precomputed bounded ticks to avoid per-list tick math.
        int24 tickLower = LISTING_TICK_LOWER;
        int24 tickUpper = LISTING_TICK_UPPER;

        // 4. Initialize the pool
        clPoolManager.initialize(poolKey, sqrtPriceX96);

        // 5. Register pool in Hook for fee collection
        PoolId poolId = poolKey.toId();
        v4PoolId = poolId;
        ITipTagSwapHook(hookAddr).registerPool(poolId, address(this));

        // 6. Add bounded-range liquidity via vault.lock() callback.
        bytes memory callbackData = abi.encode(poolKey, tickLower, tickUpper);
        vault.lock(callbackData);

        // 7. After LP is settled, send all remaining ETH to platform. Remaining token stays in this contract.
        address tiptagFeeAddress = IPump(manager).getFeeReceiver();
        uint256 remainEth = address(this).balance;
        if (remainEth > 0) {
            (bool success1, ) = tiptagFeeAddress.call{value: remainEth}("");
            require(success1, "Transfer ETH failed");
        }

        listed = true;
        emit TokenListedToDex(address(this), PoolId.unwrap(poolId), sqrtPriceX96);
    }

    /// @notice ILockCallback — called by Vault during lock() for atomic liquidity addition
    function lockAcquired(bytes calldata data) external override returns (bytes memory) {
        require(msg.sender == address(vault), "Only Vault");

        (PoolKey memory poolKey, int24 tickLower, int24 tickUpper) = abi.decode(data, (PoolKey, int24, int24));

        ICLPoolManager.ModifyLiquidityParams memory params = ICLPoolManager.ModifyLiquidityParams({
            tickLower: tickLower,
            tickUpper: tickUpper,
            liquidityDelta: int256(uint256(LISTING_LIQUIDITY_DELTA)),
            salt: bytes32(0)
        });

        (BalanceDelta callerDelta, ) = clPoolManager.modifyLiquidity(poolKey, params, "");

        // Settle amounts owed to the pool
        int128 ethOwed = callerDelta.amount0();
        int128 tokenOwed = callerDelta.amount1();

        // Settle ETH (native currency) — send ETH to Vault
        if (ethOwed < 0) {
            uint256 ethToSettle = uint256(uint128(-ethOwed));
            require(ethToSettle <= LISTING_ETH_AMOUNT, "ETH budget exceeded");
            vault.settle{value: ethToSettle}();
        }

        // Settle Token — transfer tokens to Vault then call settle
        if (tokenOwed < 0) {
            uint256 tokenToSettle = uint256(uint128(-tokenOwed));
            require(tokenToSettle <= LISTING_TOKEN_AMOUNT, "Token budget exceeded");
            vault.sync(poolKey.currency1);
            _transfer(address(this), address(vault), tokenToSettle);
            vault.settle();
        }

        // Take back any excess (should be minimal)
        if (ethOwed > 0) {
            vault.take(poolKey.currency0, address(this), uint256(uint128(ethOwed)));
        }
        if (tokenOwed > 0) {
            vault.take(poolKey.currency1, address(this), uint256(uint128(tokenOwed)));
        }

        return "";
    }

    /********************************** erc20 function ********************************/
    function name() public view override returns (string memory) {
        return _name;
    }

    function symbol() public view override returns (string memory) {
        return _symbol;
    }

    // only listed token can do erc20 transfer functions
    function _beforeTokenTransfer(address from, address to, uint256 amount) internal override {
        // Before listing, prevent unauthorized token transfers to Vault
        if (!listed && to == address(vault) && from != address(this)) {
            revert TokenNotListed();
        }
        return super._beforeTokenTransfer(from, to, amount);
    }
}
